def comps(grid,r0,r1):
    seen=set(); out=[]
    for i in range(r0,r1):
        for j in range(len(grid[0])):
            if grid[i][j] and (i,j) not in seen:
                col=grid[i][j]; stack=[(i,j)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen or not(r0<=y<r1) or not(0<=x<len(grid[0])) or grid[y][x]!=col: continue
                    seen.add((y,x)); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            if dy or dx: stack.append((y+dy,x+dx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                out.append({'col':col,'cells':sorted(cells),'top':min(ys),'bot':max(ys),'left':min(xs),'right':max(xs)})
    return out

def transform(g):
    div=next(i for i,row in enumerate(g) if set(row)=={5})
    H=len(g)
    out=[row[:] for row in g[div+1:]]
    below=comps(g,div+1,H); above=comps(g,0,div)
    keep=max(above,key=lambda s:s['right'])
    keep_left=min(s['left'] for s in below)
    btop=min(s['top'] for s in below)-div-1; bbot=max(s['bot'] for s in below)-div-1
    h=keep['bot']-keep['top']+1
    top=btop-h
    if top<0: top=bbot+1
    for (y,x) in keep['cells']:
        out[y-keep['top']+top][x-keep['left']+keep_left]=keep['col']
    return out

