                out.append({'color':col,'cells':sorted(cells),'top':min(ys),'bot':max(ys),'left':min(xs),'right':max(xs)})
    return out

def find_divider(grid, color=5):
    """The index of the first row that is one color throughout (the divider), or None."""
    return next((i for i,row in enumerate(grid) if set(row)=={color}), None)

def draw(out, shape, top, left):
    """Stamp a shape (dict of color and cells with a top/left origin) onto out with its box's top-left at (top, left)."""
